import sys
sys.path.insert(0, "model")
import cordic_vec_model as m

lines = [
    "// Auto-generated by scripts/gen_atan_vec.py - do not edit by hand",
    "localparam signed [15:0] PI_FX = %d;" % m.PI_FX,
    "function signed [15:0] atan_vec_lut(input integer idx);",
    "  case (idx)",
]
for i, a in enumerate(m.ATAN):
    lines.append("    %d: atan_vec_lut = 16'sd%d;" % (i, a))
lines += ["    default: atan_vec_lut = 16'sd0;", "  endcase", "endfunction"]

with open("rtl/cordic_vec_atan.vh", "w") as f:
    f.write("\n".join(lines) + "\n")
print("wrote rtl/cordic_vec_atan.vh")
